1|// Bounded stack of played track ids for Previous. Pure: the reader owns
2|// the array, these helpers push and pop it. Automatic switches and Next
3|// push the outgoing id; Previous pops without pushing back.
4|export const HISTORY_LIMIT = 50;
5|
6|export function pushHistory(hist: readonly string[], id: string | null): string[] {
7|  if (id === null) return [...hist];
8|  const next = [...hist, id];
9|  return next.length > HISTORY_LIMIT ? next.slice(next.length - HISTORY_LIMIT) : next;
10|}
11|
12|export function popHistory(hist: readonly string[]): { hist: string[]; id: string } | null {
13|  if (hist.length === 0) return null;
14|  return { hist: hist.slice(0, -1), id: hist[hist.length - 1] as string };
15|}

Read text file `core/music-credit.ts`.
1|// Now-playing line: Title · Composer · Source. The title stays as the
2|// manifest gives it (no nickname field exists to split off). Source is
3|// the track's short credit (artist); it drops out when it would repeat
4|// the performer. The license and full attribution join the tooltip only.
5|import type { Track } from "./music-types";
6|
7|export interface NowPlaying {
8|  line: string;
9|  full: string;
10|}
11|
12|type Credit = { title: string } & {
13|  [K in "composer" | "artist" | "license" | "attribution"]?: Pick<Track, K>[K] | null;
14|};
15|
16|export function nowPlaying(track: Credit | null): NowPlaying | null {
17|  if (track === null) return null;
18|  const who = track.composer ?? track.artist ?? null;
19|  const source = track.artist && track.artist !== who ? track.artist : null;
20|  const line = [track.title, who, source].filter((p): p is string => p !== null).join(" · ");
21|  const full = [track.title, who, source, track.license ?? null, track.attribution ?? null]
22|    .filter((p): p is string => p !== null)
23|    .join(" · ");
24|  return { line, full };
25|}

