Read text file `app/player.tsx`.
1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import { MUSIC_CONFIG, nowPlaying } from "@/core/music";
5|import { effectiveEnd, gainVolume } from "@/core/music-playback";
6|import type { StyleInfo, Track } from "@/core/music";
7|import { PlayerControls } from "./player-controls";
8|
9|// Two audio elements with equal-power crossfades. Volume lives in a
10|// ref, so the slider never re-runs the track effect or touches src.
11|// Nothing plays before the first user press. Reduced motion only
12|// affects visuals; the audio fade always runs its full length.
13|export function Player({
14|  track,
15|  replayNonce,
16|  fadeSec,
17|  canPrev,
18|  onPrev,
19|  canSkip,
20|  onSkip,
21|  styles,
22|  styleId,
23|  onStyleChange,
24|  onEnded,
25|  playlistOn,
26|  playlistLabel,
27|  onTogglePlaylist,
28|  controlsDisabled,
29|}: {
30|  track: Track | null;
31|  replayNonce: number;
32|  fadeSec: number;
33|  canPrev: boolean;
34|  onPrev: () => void;
35|  canSkip: boolean;
36|  onSkip: () => void;
37|  styles: StyleInfo[];
38|  styleId: string | null;
39|  onStyleChange: (style: string) => void;
40|  onEnded: (trackId: string) => void;
41|  playlistOn: boolean;
42|  playlistLabel: string | null;
43|  onTogglePlaylist: () => void;
44|  controlsDisabled: boolean;
45|}) {
46|  const firstRef = useRef<HTMLAudioElement | null>(null);
47|  const secondRef = useRef<HTMLAudioElement | null>(null);
48|  const audibleRef = useRef(0);
49|  const levelRef = useRef<[number, number]>([1, 0]);
50|  const gainRef = useRef<[number, number]>([0, 0]);
51|  const segmentEndRef = useRef<string | null>(null);
52|  const volumeRef = useRef(0.8);
53|  const fadeRef = useRef<number | null>(null);
54|  const loopArmedRef = useRef<string | null>(null);
55|  const trackRef = useRef<Track | null>(track);
56|  trackRef.current = track;
57|  const fadeSecRef = useRef(fadeSec);
58|  fadeSecRef.current = fadeSec;
59|  const onEndedRef = useRef(onEnded);
60|  onEndedRef.current = onEnded;
61|  const playingRef = useRef(false);
62|  const startedRef = useRef(false);
63|  const firstPlayRef = useRef(true);
64|
65|  // Scheduler fade when set, else the config default; never 0 mid session.
66|  function loopFadeSec() {
67|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
68|  }
69|  const [started, setStarted] = useState(false);
70|  const [playing, setPlaying] = useState(false);
71|  const [volume, setVolume] = useState(0.8);
72|  const requestPlayRef = useRef((_: Track, __: number) => {});
73|
74|  const [reducedMotion, setReducedMotion] = useState(
75|    () =>
76|      typeof window !== "undefined" &&
77|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
78|  );
79|
80|  useEffect(() => {
81|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
82|    if (!query) return;
83|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
84|    query.addEventListener("change", onChange);
85|    return () => query.removeEventListener("change", onChange);
86|  }, []);
87|
88|  function applyLevels() {
89|    const els = [firstRef.current, secondRef.current];
90|    els.forEach((el, i) => {
91|      if (el)
92|        el.volume = gainVolume(
93|          levelRef.current[i] ?? 0,
94|          volumeRef.current,
95|          gainRef.current[i] ?? 0,
96|        );
97|    });
98|  }
99|
100|  function cancelFade() {
101|    if (fadeRef.current !== null) {
102|      cancelAnimationFrame(fadeRef.current);
103|      fadeRef.current = null;
104|    }
105|  }
106|
107|  // Assigned each render so handlers always see fresh refs. Fades from
108|  // the currently louder element to the newest track; a mid-fade request
109|  // cancels the pending fade and starts from current levels.
110|  requestPlayRef.current = (next: Track, durSec: number) => {
111|    const els = [firstRef.current, secondRef.current];
112|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
113|    const dstIdx = 1 - srcIdx;
114|    const srcEl = els[srcIdx];
115|    const dst = els[dstIdx];
116|    if (!srcEl || !dst) return;
117|    cancelFade();
118|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
119|    trackRef.current = next;
120|    segmentEndRef.current = null;
121|    gainRef.current[dstIdx] = next.gainDb ?? 0;
122|    dst.src = next.src;
123|    dst.onloadedmetadata = () => {
124|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
125|        try {
126|          dst.currentTime = next.startSec;
127|        } catch {
128|          // Past the end; leave playback at zero.
129|        }
130|      }
131|    };
132|    if (!playingRef.current || durSec <= 0) {
133|      levelRef.current = [0, 0];
134|      levelRef.current[dstIdx] = 1;
135|      audibleRef.current = dstIdx;
136|      srcEl.pause();
137|      applyLevels();
138|      if (playingRef.current) void dst.play().catch(() => undefined);
139|      return;
140|    }
141|    if (playingRef.current) void dst.play().catch(() => undefined);
142|    const startSrc = levelRef.current[srcIdx] ?? 0;
143|    const startDst = levelRef.current[dstIdx] ?? 0;
144|    let t0 = performance.now();
145|    let prev = t0;
146|    const tick = (now: number) => {
147|      // Pause freezes the fade; resume continues from the frozen point.
148|      if (!playingRef.current) {
149|        t0 += now - prev;
150|        prev = now;
151|        fadeRef.current = requestAnimationFrame(tick);
152|        return;
153|      }
154|      prev = now;
155|      const t = Math.min(1, (now - t0) / (durSec * 1000));
156|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
157|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
158|      applyLevels();
159|      if (t < 1) {
160|        fadeRef.current = requestAnimationFrame(tick);
161|        return;
162|      }
163|      fadeRef.current = null;
164|      levelRef.current[srcIdx] = 0;
165|      levelRef.current[dstIdx] = 1;
166|      audibleRef.current = dstIdx;
167|      applyLevels();
168|      srcEl.pause();
169|    };
170|    fadeRef.current = requestAnimationFrame(tick);
171|  };
172|
173|  const trackId = track?.id ?? null;
174|  useEffect(() => {
175|    const next = trackRef.current;
176|    if (!started || !next) {
177|      // Before the first press, swaps only change src.
178|      if (!started && next) {
179|        const el = [firstRef.current, secondRef.current][audibleRef.current];
180|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
181|        gainRef.current[audibleRef.current] = next.gainDb ?? 0;
182|        applyLevels();
183|      }
184|      return;
185|    }
186|    // The single start path: fade 0 on the very first press. replayNonce
187|    // re-cues the same track (one-track playlist wrap); nothing else is a dep
188|    // so volume, pause/play, and re-renders never restart the track.
189|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
190|    firstPlayRef.current = false;
191|    requestPlayRef.current(next, dur);
192|  }, [started, trackId, replayNonce]);
193|
194|  useEffect(() => cancelFade, []);
195|
196|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
197|    const next = trackRef.current;
198|    if (!next || index !== audibleRef.current) return;
199|    const end = effectiveEnd(next.endSec, el.duration);
200|    if (!Number.isFinite(end)) return;
201|    // A non-looping or playlist track ends at the segment end, where the
202|    // media may keep playing, so fire the ended path once per play.
203|    if (!next.loop || playlistOn) {
204|      if (el.currentTime >= end && segmentEndRef.current !== next.id) {
205|        segmentEndRef.current = next.id;
206|        onEndedRef.current(next.id);
207|      }
208|      return;
209|    }
210|    const fade = loopFadeSec();
211|    if (end <= fade * 2) return;
212|    const remain = end - el.currentTime;
213|    if (remain <= fade && loopArmedRef.current !== next.id) {
214|      loopArmedRef.current = next.id;
215|      requestPlayRef.current(next, fade);
216|    } else if (remain > fade + 1) {
217|      loopArmedRef.current = null;
218|    }
219|  }
220|
221|  function handleEnded(index: number) {
222|    const els = [firstRef.current, secondRef.current];
223|    // An element that ends while a fade is running is the one fading out.
224|    if (index !== audibleRef.current || fadeRef.current !== null) {
225|      els[index]?.pause();
226|      return;
227|    }
228|    const next = trackRef.current;
229|    if (!next || segmentEndRef.current === next.id) return;
230|    if (next.loop && !playlistOn) {
231|      requestPlayRef.current(next, loopFadeSec());
232|      return;
233|    }
234|    segmentEndRef.current = next.id;
235|    onEndedRef.current(next.id);
236|  }
237|
238|  function toggle() {
239|    const both = [firstRef.current, secondRef.current];
240|    if (!startedRef.current) {
241|      startedRef.current = true;
242|      setStarted(true);
243|      playingRef.current = true;
244|      setPlaying(true);
245|      return;
246|    }
247|    if (playingRef.current) {
248|      for (const el of both) el?.pause();
249|      playingRef.current = false;
250|      setPlaying(false);
251|      return;
252|    }
253|    playingRef.current = true;
254|    setPlaying(true);
255|    let heard = false;
256|    both.forEach((el, i) => {
257|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
258|        heard = true;
259|        void el.play().catch(() => undefined);
260|      }
261|    });
262|    const next = trackRef.current;
263|    if (!heard && next) requestPlayRef.current(next, 0);
264|  }
265|
266|  function changeVolume(value: number) {
267|    setVolume(value);
268|    volumeRef.current = value;
269|    applyLevels();
270|  }
271|
272|  const now = track ? nowPlaying(track) : null;
273|
274|  return (
275|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
276|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
277|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
278|      <button type="button" className="skip" onClick={onPrev} disabled={!canPrev} aria-label="Previous track" title="Previous track">
279|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
280|          <rect x="2.5" y="3" width="2" height="10" rx="0.5" />
281|          <path d="M13.5 3.5v9L6 8z" />
282|        </svg>
283|      </button>
284|      <button type="button" className="skip" onClick={toggle} aria-label={playing ? "Pause" : "Play"} title={playing ? "Pause" : "Play"}>
285|        {playing ? (
286|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
287|            <rect x="4" y="3" width="2.6" height="10" rx="0.5" />
288|            <rect x="9.4" y="3" width="2.6" height="10" rx="0.5" />
289|          </svg>
290|        ) : (
291|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
292|            <path d="M5 3.5v9l7.5-4.5z" />
293|          </svg>
294|        )}
295|      </button>
296|      <button type="button" className="skip" onClick={onSkip} disabled={!canSkip} aria-label="Next track" title="Next track">
297|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
298|          <path d="M2.5 3.5v9l7.5-4.5z" />
299|          <rect x="11.5" y="3" width="2" height="10" rx="0.5" />
300|        </svg>
301|      </button>
302|      <span className="player-track" aria-live="polite" title={now?.full}>
303|        {now?.line ?? "Music unavailable"}
304|      </span>
305|      <label className="player-volume">
306|        Volume
307|        <input
308|          type="range"
309|          min={0}
310|          max={1}
311|          step={0.05}
312|          value={volume}
313|          onChange={(e) => changeVolume(Number(e.target.value))}
314|          aria-label="Volume"
315|        />
316|      </label>
317|      <PlayerControls
318|        styles={styles}
319|        styleId={styleId}
320|        onStyleChange={onStyleChange}
321|        playlistLabel={playlistLabel}
322|        playlistOn={playlistOn}
323|        onTogglePlaylist={onTogglePlaylist}
324|        controlsDisabled={controlsDisabled}
325|      />
326|      {track?.sourceUrl ? (
327|        <a className="player-note" href={track.sourceUrl} rel="noopener noreferrer" target="_blank">
328|          Source
329|        </a>
330|      ) : null}
331|    </div>
332|  );
333|}

